# partition.py
import itertools, sys

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

# Precompute all valid triples (a,b,c) with a<b and a+b=c
triples = []
for a, b in itertools.combinations(L, 2):
    c = a + b
    if c in L and c != a and c != b:
        triples.append((a, b, c))

# Backtracking exact cover search
used = set()
solution = []

def backtrack(start):
    if len(solution) == 15:
        return True
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        # choose
        used.update([a, b, c])
        solution.append((a, b, c))
        if backtrack(i + 1):
            return True
        # undo
        used.difference_update([a, b, c])
        solution.pop()
    return False

if backtrack(0):
    print("Found partition:")
    for tri in solution:
        print(tri)
    # Emit witness for the host
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"partition": solution}}
    print("WITNESS:", witness)
else:
    print("No partition found.")
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "nodes_explored": None, "method": "backtrack"}
    print("WITNESS:", witness)

#!/usr/bin/env python3
import sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
nums = list(L)
nums.sort()
# Precompute possible triples (a,b,c) where a+b=c
triples = []
index = {v:i for i,v in enumerate(nums)}
for i, a in enumerate(nums):
    for j in range(i+1, len(nums)):
        b = nums[j]
        c = a + b
        if c in index:
            triples.append((a,b,c))
# Build adjacency: for each number, which triples include it
from collections import defaultdict
adj = defaultdict(list)
for t in triples:
    for v in t:
        adj[v].append(t)

used = set()
solution = []

sys.setrecursionlimit(10000)

def search():
    if len(solution) == 15:
        return True
    # pick smallest unused number to branch
    for v in nums:
        if v not in used:
            start = v
            break
    for t in adj[start]:
        a,b,c = t
        if a in used or b in used or c in used:
            continue
        # enforce ordering a<b to avoid duplicates (already true from generation)
        used.update(t)
        solution.append(t)
        if search():
            return True
        solution.pop()
        used.difference_update(t)
    return False

found = search()
if not found:
    print('WITNESS:', json.dumps({"polarity":"negative","evidence":{"path":"execution://witness"},"basis":"proof","argument":"No partition exists for the given set."}))
    sys.exit(0)
# output witness
witness_data = {"partition": solution}
print('WITNESS:', json.dumps({"polarity":"positive","evidence":{"path":"execution://witness"},"data":witness_data}))
